  config = config_adblock,
  section = "global",
  type = "adblock",
  options = {
    "adb_enabled", "adb_srcarc", "adb_srcfile", "adb_dns", "adb_fetchutil", "adb_fetchparm",
    "adb_trigger", "adb_debug", "adb_backup", "adb_backupdir", "adb_safesearch",
  }
}

mapper("uci_1to1").registerSimpleMap(adblock_global)

